// src/utils/certificateUtils.js
import jsPDF from 'jspdf';

export const generateProfessionalCertificatePDF = (certificateData) => {
  return new Promise((resolve) => {
    const pdf = new jsPDF('landscape', 'mm', 'a4');
    const pageWidth = pdf.internal.pageSize.getWidth();
    const pageHeight = pdf.internal.pageSize.getHeight();
    
    // Couleurs de la plateforme
    const primaryColor = [59, 130, 246]; // blue-500
    const secondaryColor = [139, 92, 246]; // violet-500
    const accentColor = [16, 185, 129]; // green-500
    const textDark = [31, 41, 55]; // gray-800
    const textLight = [107, 114, 128]; // gray-500
    
    // Fond dégradé professionnel
    pdf.setFillColor(248, 250, 252); // gray-50
    pdf.rect(0, 0, pageWidth, pageHeight, 'F');
    
    // Bordure décorative
    pdf.setDrawColor(...primaryColor);
    pdf.setLineWidth(2);
    pdf.rect(10, 10, pageWidth - 20, pageHeight - 20);
    
    // En-tête avec logo
    pdf.setFillColor(...primaryColor);
    pdf.rect(0, 0, pageWidth, 30, 'F');
    
    pdf.setFontSize(20);
    pdf.setTextColor(255, 255, 255);
    pdf.text('EDUPLATFORM', pageWidth / 2, 20, { align: 'center' });
    
    // Titre principal
    pdf.setFontSize(32);
    pdf.setTextColor(...primaryColor);
    pdf.text('CERTIFICAT DE RÉUSSITE', pageWidth / 2, 60, { align: 'center' });
    
    // Sous-titre
    pdf.setFontSize(14);
    pdf.setTextColor(...textLight);
    pdf.text('Décerné à', pageWidth / 2, 80, { align: 'center' });
    
    // Nom de l'étudiant
    pdf.setFontSize(28);
    pdf.setTextColor(...textDark);
    pdf.text(certificateData.studentName.toUpperCase(), pageWidth / 2, 105, { align: 'center' });
    
    // Description du cours
    pdf.setFontSize(16);
    pdf.setTextColor(...textLight);
    pdf.text('a complété avec succès le cours', pageWidth / 2, 125, { align: 'center' });
    
    // Titre du cours
    pdf.setFontSize(20);
    pdf.setTextColor(...secondaryColor);
    pdf.text(`"${certificateData.courseTitle}"`, pageWidth / 2, 145, { align: 'center' });
    
    // Informations détaillées
    const infoY = 165;
    pdf.setFontSize(12);
    pdf.setTextColor(...textDark);
    
    pdf.text(`Score final: ${certificateData.finalScore}%`, 50, infoY);
    pdf.text(`Date d'émission: ${new Date(certificateData.issueDate).toLocaleDateString('fr-FR')}`, pageWidth - 50, infoY, { align: 'right' });
    
    pdf.text(`Durée: ${certificateData.duration}`, 50, infoY + 15);
    pdf.text(`Niveau: ${certificateData.level}`, pageWidth - 50, infoY + 15, { align: 'right' });
    
    // QR Code pour vérification (espace réservé)
    pdf.setFontSize(10);
    pdf.setTextColor(...textLight);
    pdf.text('Scannez pour vérifier', pageWidth / 2, infoY + 40, { align: 'center' });
    
    // Rectangle pour QR Code
    pdf.setDrawColor(...textLight);
    pdf.rect(pageWidth / 2 - 20, infoY + 45, 40, 40);
    pdf.text('QR CODE', pageWidth / 2, infoY + 68, { align: 'center' });
    
    // ID du certificat
    pdf.setFontSize(9);
    pdf.setTextColor(...textLight);
    pdf.text(`ID: ${certificateData.certificateId}`, pageWidth / 2, infoY + 85, { align: 'center' });
    
    // Pied de page avec signatures
    const footerY = pageHeight - 40;
    
    // Signature instructeur
    pdf.setDrawColor(...textLight);
    pdf.line(60, footerY, 120, footerY);
    pdf.setFontSize(10);
    pdf.text('Instructeur du cours', 90, footerY + 10, { align: 'center' });
    
    // Signature plateforme
    pdf.line(pageWidth - 120, footerY, pageWidth - 60, footerY);
    pdf.text('Directeur EduPlatform', pageWidth - 90, footerY + 10, { align: 'center' });
    
    // Mention légale
    pdf.setFontSize(8);
    pdf.setTextColor(...textLight);
    pdf.text('Ce certificat est délivré électroniquement et peut être vérifié en ligne', pageWidth / 2, pageHeight - 15, { align: 'center' });
    
    resolve(pdf.output('blob'));
  });
};

export const downloadPDF = (pdfBlob, fileName = 'certificat.pdf') => {
  const url = URL.createObjectURL(pdfBlob);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  link.style.display = 'none';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

export const printPDF = (pdfBlob) => {
  const url = URL.createObjectURL(pdfBlob);
  const iframe = document.createElement('iframe');
  iframe.style.display = 'none';
  iframe.src = url;
  document.body.appendChild(iframe);
  iframe.onload = () => {
    iframe.contentWindow?.print();
  };
};
